(async () => {
  const lab = await window.__mymechanics.std.render.lab();
  const o = { width: 64, height: 48, samples: 24 };
  const none = await lab.labRender('glass', { ...o, hidden: true, seed: 1 });
  const none2 = await lab.labRender('glass', { ...o, hidden: true, seed: 4 });
  const air = await lab.labRender('glass', { ...o, ior: 1.0, seed: 2 });
  const glass = await lab.labRender('glass', { ...o, ior: 1.5, seed: 3 });
