  return `noise ${noise.toFixed(3)} air ${dAir.toFixed(3)} glass ${dGlass.toFixed(3)}`;
})()

(async () => {
  const lab = await window.__mymechanics.std.render.lab();
  const region = [0.46, 0.44, 0.54, 0.56];
  const res = {};
  for (const env of ['sunset', 'daylight']) {
    const r = await lab.labRender('metal', { width: 64, height: 48, samples: 16, env });
    const got = lab.regionMean(r, ...region).slice(0, 3);
    const want = lab.mirrorExpected(env, region, 64, 48);
    const err = Math.max(...got.map((v, i) => Math.abs(v - want[i]) / Math.max(0.05, want[i])));
    if (!(err < 0.2)) throw new Error(`${env}: got ${got.map((v) => v.toFixed(3))} want ${want.map((v) => v.toFixed(3))}`);
    res[env] = got[0] / Math.max(1e-4, got[2]);
  }
  if (!(res.sunset > res.daylight * 1.3)) throw new Error(`red/blue sunset ${res.sunset} daylight ${res.daylight}`);
  return `red/blue sunset ${res.sunset.toFixed(2)} daylight ${res.daylight.toFixed(2)}`;
})()

(async () => {
  const lab = await window.__mymechanics.std.render.lab();
  const r = await lab.labRender('shadow', { width: 64, height: 64, samples: 32 });
  // Top view, 160 mm across: the studio sun is at azimuth 35°, the shadow toward 215°.
  const at = (x, y) => [(x + 80) / 160, (80 - y) / 160];
  const patch = ([fx, fy]) => lab.regionLum(r, fx - 0.03, fy - 0.03, fx + 0.03, fy + 0.03);
  const shadow = patch(at(-27, -19)); const lit = patch(at(27, 19)); const far = patch(at(-70, 70));
  if (!(shadow < 0.65 * lit && Math.abs(lit - far) < 0.25 * far)) throw new Error(`shadow ${shadow} lit ${lit} far ${far}`);
  return `shadow/lit ${(shadow / lit).toFixed(2)}`;
})()

