(async () => {
  const m = window.__mymechanics;
  const t = m.std.render.tracer;
  const before = t.meanImage();
  m.std.renderSettings.region = { x0: 0.25, y0: 0.25, x1: 0.5, y1: 0.5 };
  m.std.renderSettings.env = 'sunset';
  await m.std.render.rerender({ keepOutside: true });
  await new Promise((r) => { const w = () => (m.state.editing?.status?.done ? r() : setTimeout(w, 100)); w(); });
  const after = t.meanImage();
  const W = after.width; const H = after.height;
  let outsideSame = true; let insideChanged = 0;
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    const i = (y * W + x) * 4; const fx = (x + 0.5) / W; const fy = 1 - (y + 0.5) / H;
    const inside = fx > 0.25 && fx < 0.5 && fy > 0.25 && fy < 0.5;
    const d = Math.abs(after.data[i] - before.data[i]) + Math.abs(after.data[i + 2] - before.data[i + 2]);
    if (!inside && d > 1e-5) outsideSame = false;
    if (inside && d > 1e-3) insideChanged += 1;
  }
  const tilesInside = t.tiles.every((tile) => tile.x >= Math.floor(W * 0.25) && tile.x + tile.w <= Math.ceil(W * 0.5) && tile.y >= Math.floor(H * 0.5) && tile.y + tile.h <= Math.ceil(H * 0.75));
  m.std.renderSettings.region = null;
  return `${outsideSame} ${insideChanged > 100} ${tilesInside}`;
})()

